# Runtime paths: source and working data are separate.
import os as _os
from pathlib import Path as _RuntimePath
_SOURCE_ROOT = _RuntimePath(__file__).resolve().parents[1]
_WORKSPACE = _RuntimePath(_os.environ.get("HCC_WORKSPACE", str(_SOURCE_ROOT))).resolve()
_os.chdir(_WORKSPACE)
(_WORKSPACE / "outputs").mkdir(exist_ok=True)
from pathlib import Path
import csv,json
root=Path('work/cnv');results=json.loads(Path('work/cnv_signature_results.json').read_text()) if Path('work/cnv_signature_results.json').exists() else []
labels=[]
for p in [f'HCC{n:02}' for n in range(3,11)]:
 f=root/p/'cell_labels.tsv'
 if f.exists():labels+=list(csv.DictReader(f.open(),delimiter='\t'))
if labels:
 with open('outputs/GSE149614_RNA_CNV_hucre_etiketleri.tsv','w') as f:
  writer=csv.DictWriter(f,fieldnames=list(labels[0]),delimiter='\t');writer.writeheader();writer.writerows(labels)
md=['# inferCNV: malignite adayı ayrımı ve imza duyarlılığı','','10 Ekim 2026','','## Hesaplama kapsamı','','GSE149614’ün sekiz eşleşmiş hastasındaki 13.762 hepatositin ham tam sayı sayımları kullanıldı. Komşu dokudan hasta başına T/NK, B ve endotel tiplerinin her birinden en çok 100 hücre referans olarak seçildi (tohum 20261010). Toplam 2367 referans hücresi vardır. HCC10’da B referansı 67 hücredir. RNA sayımlarının önceden filtrelenmiş yayımlanmış matristen geldiği korunur; ham droplet/BAM değildir.','','Gen konumları GRCh38 GENCODE v38 anotasyonundan çıkarıldı. 25.712 genin 22.304’ü otozomal tekil konuma eşleşti; belirsiz çoklu konumlar ve cinsiyet/mitokondri kromozomları dışarıda tutuldu. 47 genlik göçle ilişkili hepatosit imzasının barkod sırası ile CNV etiketleri birebir eşleştirildi.','','Resmî inferCNV R paketi 1.22.0 çalıştırıldı. R 4.4.1, JAGS 4.3.2 ve Seurat 5.4.0 kullanıldı. Ana parametreler: cutoff=0.1, 101 genlik düzeltme penceresi, i6 HMM, Leiden altkümeleri, denoise=TRUE, iki iş parçacığı. HMM tahmini altküme düzeyinde yapılıp barkod eşlemesiyle hücrelere aktarıldı. HMM grupları dokular içinde kurulmuştur; bunlar DNA ile doğrulanmış evrimsel klonlar değildir.','','HCC04, HCC05, HCC07, HCC08, HCC09 ve HCC10 çalıştırmalarında yalnızca sabit HMM satırlarının raporlama konsensüsü hızlandırıldı: aynı durum değerini taşıyan satırlarda ilk sütun kullanıldı, diğer matrislerde özgün inferCNV işlevine dönüldü. 60 sentetik matris ve HCC06’nın 28 gerçek HMM altkümesinde özgün konsensüs vektörleriyle birebir eşitlik doğrulandı. Tahmin, eşikler veya altküme üyelikleri değiştirilmedi.', '', 'BayesMaxPNormal=0 olduğundan ek Bayes ağ filtresi çalıştırılmadı. HMM posterior güveni veya genomik doğrulama ileri sürülmez. CopyKAT bu aşamada çalıştırılmadı.','','## İkinci referans ve etiketleme','','Her hasta için aynı veriye komşu hepatositleri referans alan ikinci inferCNV hattı uygulandı. Bu duyarlılık hattında HMM kapalı, düzeltilmiş göreli RNA-CNV profilleri kullanıldı. Komşu hepatositler DNA ile doğrulanmış diploid hücreler değildir.','','“RNA_CNV_supported_candidate” etiketi için ana i6 hattında en az iki otozomda en az 10 Mb genişliğinde nötr olmayan segment gerekir. Aynı segmentte ikinci hattın ortalama sinyali de aynı yönde kalmalıdır; eşik 0.05 ile komşu hepatositlerdeki mutlak segment ortalamalarının %99 persentilinin büyük olanıdır. İkinci matriste en az 10 gen bulunmayan segment değerlendirilmez. Bir CNV grubunda bu koşulları sağlayan en az 20 hepatosit bulunmalıdır. Kurallar etiket ve onarım sonucu hesaplanmadan önce yazıldı; keşif amaçlıdır, klinik olarak kalibre edilmiş değildir.','','Ana hatta geniş çağrı olup doğrulama koşullarını karşılamayan hücreler “CNV_signal_indeterminate”; ana hatta geniş çağrısı bulunmayanlar “CNV_low_or_undetected” olarak tutuldu. İki etiket de “benign” anlamına gelmez. Genomik olarak sessiz malign hücreler olabilir. RNA’da geniş ifade blokları, soy veya durum farklarını da yansıtabilir.','','## Barkod sonuçları','','| Hasta | Komşu aday / toplam | Tümör aday / toplam | Tümör belirsiz | Tümör CNV düşük/saptanmayan |','|---|---:|---:|---:|---:|']
for r in results:
 a=r['labels']['Adjacent'];b=r['labels']['Tumor'];md.append(f"| {r['patient']} | {a['RNA_CNV_supported_candidate']}/{sum(a.values())} | {b['RNA_CNV_supported_candidate']}/{sum(b.values())} | {b['CNV_signal_indeterminate']} | {b['CNV_low_or_undetected']} |")
md+=['','## Aday tümör hücrelerinde skor karşılaştırması','','Karşılaştırma RNA-CNV destekli tümör hepatositleri ile aday etiketi almamış komşu hepatositler arasındadır. Komşu hücreler benignliği genomik olarak doğrulanmış kontrol hücreleri değildir. Hücre seçimi önceki tüm-soy analizinin hedef popülasyonunu değiştirir.','','| Hasta | Komşu / aday T | Ham fark | Beş kovaryatlı regresyon | Örtüşme ağırlıklı fark | ESS N/T |','|---|---:|---:|---:|---:|---:|']
for r in results:
 b=r.get('balancing');reg=r.get('regression')
 if b:
  o=b['overlap'];md.append(f"| {r['patient']} | {r['n_adjacent']}/{r['n_candidate_T']} | {b['raw']['difference']:+.4f} | {format(reg['difference'],'+.4f') if 'difference' in reg else 'tanımlanamıyor'} | {o['difference']:+.4f} | {o['ESS_N']:.1f}/{o['ESS_T']:.1f} |")
 else:md.append(f"| {r['patient']} | {r['n_adjacent']}/{r['n_candidate_T']} | yeterli hücre yok | — | — | — |")
md+=['','Hasta düzeyinde güven aralığı veya p değeri hesaplanmadı. Hücre sayısı bağımsız hasta sayısının yerine geçmez. CNV ile aynı RNA matrisinden hücre seçmek, skorla bağlantılı seçim yaratabilir; imza genlerinin çıkarıldığı CNV duyarlılığı ve ikinci algoritma karşılaştırması yapılmadı. Bütün adaylar doğrulanmış malign hücreler şeklinde sunulamaz. GSE189175 için bu aşamada CNV etiketi üretilmedi; o kohortun sonuçları keşif amaçlı hepatosit soyunda doku karşılaştırmasıdır.','','## Son kontrol ve okuma', '', 'Sekiz hastanın 13.762 hepatositinin barkod kapsamı birebir doğrulandı. 10.508 tümör hepatositi RNA-CNV destekli aday olarak etiketlendi; diğer 3254 hepatosit belirsiz kaldı. Bu 3254 hücrenin 1788’i komşu, 1466’sı tümör dokusundadır. Komşu hücrelerin ikinci hattın referansına girmesi nedeniyle sıfır aday çıkması bağımsız bir benignlik doğrulaması değildir.', '', 'Aday tümör hücreleriyle örtüşme ağırlıklı fark dört hastada pozitif, dört hastada negatiftir. Eşit hasta ağırlıklı ortalama −0.00431’dir; bu betimleyici sayı popülasyon ortalama ilişkisinin yokluğunu kanıtlamaz. HCC05’te regresyon ve örtüşme ağırlıklandırması farklı yön verir. Aday altkümede HCC05 ve HCC07 normal doku ESS değerleri yaklaşık 19.5 ve 18.6’dır. Maligniteye göre seçim ve daha iyi kovaryat dengesi bilgi kaybını otomatik olarak engellemez.', '', 'Aday hücre karşılaştırmalarının eğilim skorları R glm ile, regresyonları ağırlıklı R lm ile bağımsız tekrar hesaplandı. En büyük uygulamalar arası mutlak fark örtüşme tahmininde 3.86e−9, regresyonda 5.0e−15 düzeyindedir. Bu sayısal doğrulama biyolojik sınıflandırmanın doğruluğunu ölçmez.', '', '[Sekiz hastanın RNA-CNV profilleri](GSE149614_inferCNV_sekiz_hasta.png): ikinci referans hattının 10 Mb gen konumu aralıklarına göre ortalama log2 göreli sinyali. Görsel için her dokudan en çok 150 hücre deterministik örneklendi; sınıflandırmada bütün hücreler kullanıldı. Çizgiler doku ve etiket sınırlarını gösterir. Renkler DNA kopya sayıları değildir.', '', 'İmza, yayımlanmış insan göçle ilişkili hepatosit listesinin 47 genlik uyarlamasıdır; genel rejenerasyonun işlevsel ölçümü değildir. [İmzanın kaynak çalışması](https://www.nature.com/articles/s41586-024-07376-2).', '', '## Kaynaklar','','[inferCNV resmî uygulaması ve çalışma kılavuzu](https://github.com/broadinstitute/infercnv/wiki/Running-InferCNV) · [GENCODE v38](https://www.gencodegenes.org/human/release_38.html) · [GSE149614](https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE149614)','','[Barkod etiketleri](GSE149614_RNA_CNV_hucre_etiketleri.tsv) · [İki referansın HCC06 görsel kontrolü](HCC06_inferCNV_referans_duyarliligi.png)']
if len(results)<8:md.insert(4,f'**Ara rapor: {len(results)}/8 hasta için etiket ve karşılaştırma mevcut. Tamamlanmış sekiz hasta sonucu değildir.**\n')
Path('outputs/inferCNV_malignite_ayrimi.md').write_text('\n'.join(md)+'\n');print(len(results),len(labels))
